import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int n = in.nextInt();
        for (int j = 0; j < n; j++) {
            String nom = in.next();
            int rejim = Integer.parseInt(in.next(), 8);
            List<String> belgilar = new ArrayList<>();
            if ((rejim & 2) != 0) {
                belgilar.add("world-writable");
            }
            System.out.println(nom + ": " + (belgilar.isEmpty() ? "none" : String.join(", ", belgilar)));
        }
    }
}

